import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.CRFziyHp.js";const o="/images/placeholder-setup-wizard.svg",g=JSON.parse('{"title":"初始化向导","description":"","frontmatter":{},"headers":[],"relativePath":"guide/setup-wizard.md","filePath":"guide/setup-wizard.md","lastUpdated":1785013113000}'),s={name:"guide/setup-wizard.md"};function h(i,t,l,n,c,b){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="初始化向导" tabindex="-1">初始化向导 <a class="header-anchor" href="#初始化向导" aria-label="Permalink to &quot;初始化向导&quot;">​</a></h1><p>首次部署时，通过浏览器打开 <strong><code>/setup</code></strong> 完成数据库、Redis、域名、密钥等 <strong>一次性</strong> 配置。向导完成后会写入 <code>config.yaml</code>、自动建表，之后该地址将不可用。</p><p><img src="'+o+`" alt="Setup 向导"></p><hr><h2 id="访问条件" tabindex="-1">访问条件 <a class="header-anchor" href="#访问条件" aria-label="Permalink to &quot;访问条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条件</th><th>说明</th></tr></thead><tbody><tr><td>地址</td><td><code>http://服务器IP:8080/setup</code> 或 <code>https://你的域名/setup</code></td></tr><tr><td>服务已启动</td><td>已执行 <code>go run ./src/cmd/server</code> 或生产进程</td></tr><tr><td>未完成安装</td><td><code>config.yaml</code> 中 <code>app.setup_completed</code> 为 <code>false</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">HTTPS</p><p>生产环境强烈建议 <strong>先配置 SSL</strong> 再访问 setup。非 HTTPS 且非 localhost 时页面会提示风险。</p></div><hr><h2 id="向导步骤总览" tabindex="-1">向导步骤总览 <a class="header-anchor" href="#向导步骤总览" aria-label="Permalink to &quot;向导步骤总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>名称</th><th>主要内容</th></tr></thead><tbody><tr><td>00</td><td>站点授权</td><td>拉取 license（部分部署可跳过）</td></tr><tr><td>01</td><td>应用与网络</td><td>项目名、端口、网站地址、跨域</td></tr><tr><td>02</td><td>数据存储</td><td>MySQL、Redis、Meilisearch、Gorse 等</td></tr><tr><td>03</td><td>安全与密钥</td><td>JWT 密钥、加密密钥、权限策略</td></tr><tr><td>04</td><td>确认安装</td><td>测试连接 → 写入配置 → 建表</td></tr></tbody></table><hr><h2 id="步骤-00-站点授权" tabindex="-1">步骤 00：站点授权 <a class="header-anchor" href="#步骤-00-站点授权" aria-label="Permalink to &quot;步骤 00：站点授权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>授权编号</td><td>形如 <code>lic_xxx</code>，从授权方获取</td></tr><tr><td>拉取密钥</td><td>授权站实例详情中复制</td></tr><tr><td><strong>拉取授权文件</strong></td><td>下载 license 到服务器</td></tr></tbody></table><p>若检测到官方授权域名，此步可能自动跳过，直接进入配置。</p><hr><h2 id="步骤-01-应用与网络" tabindex="-1">步骤 01：应用与网络 <a class="header-anchor" href="#步骤-01-应用与网络" aria-label="Permalink to &quot;步骤 01：应用与网络&quot;">​</a></h2><h3 id="应用基础" tabindex="-1">应用基础 <a class="header-anchor" href="#应用基础" aria-label="Permalink to &quot;应用基础&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th><th>常见错误</th></tr></thead><tbody><tr><td>项目名称</td><td>推荐</td><td>后台与日志显示名</td><td>—</td></tr><tr><td>网站端口</td><td>必填</td><td>默认 <code>8080</code>，Go 进程监听端口</td><td>与 Nginx 反代端口不一致</td></tr><tr><td>网站地址</td><td><strong>必填</strong></td><td>完整 URL，如 <code>https://campus.example.com</code></td><td>须与后续微信回调、H5 域名 <strong>完全一致</strong>；填错导致登录/支付回调失败</td></tr></tbody></table><p>页面会 <strong>实时校验</strong> 当前访问域名与填写地址是否匹配。</p><h3 id="跨域访问" tabindex="-1">跨域访问 <a class="header-anchor" href="#跨域访问" aria-label="Permalink to &quot;跨域访问&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>允许访问的前端地址</td><td>CORS 白名单，<strong>每行一个</strong> Origin</td></tr><tr><td>允许携带凭证</td><td>一般开启</td></tr></tbody></table><p><strong>示例（生产）：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://campus.example.com</span></span>
<span class="line"><span>https://www.campus.example.com</span></span></code></pre></div><p>若有独立 H5 域名、管理后台域名，都要列入。</p><hr><h2 id="步骤-02-数据存储" tabindex="-1">步骤 02：数据存储 <a class="header-anchor" href="#步骤-02-数据存储" aria-label="Permalink to &quot;步骤 02：数据存储&quot;">​</a></h2><h3 id="数据库-mysql-必填" tabindex="-1">数据库 MySQL（必填） <a class="header-anchor" href="#数据库-mysql-必填" aria-label="Permalink to &quot;数据库 MySQL（必填）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>默认/示例</th><th>说明</th></tr></thead><tbody><tr><td>服务器地址</td><td><code>127.0.0.1</code></td><td>Docker 部署勿填 localhost 若 MySQL 在别的容器</td></tr><tr><td>端口</td><td><code>3306</code></td><td>—</td></tr><tr><td>用户名</td><td>—</td><td>建议专用账号，非 root</td></tr><tr><td>密码</td><td>—</td><td>—</td></tr><tr><td>数据库名</td><td>如 <code>lingmengv2</code></td><td><strong>须提前创建空库</strong>，或账号有建库权限</td></tr><tr><td>字符集</td><td><code>utf8mb4</code></td><td><strong>必须 utf8mb4</strong>，否则 emoji 乱码</td></tr></tbody></table><h3 id="缓存-redis-必填" tabindex="-1">缓存 Redis（必填） <a class="header-anchor" href="#缓存-redis-必填" aria-label="Permalink to &quot;缓存 Redis（必填）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>地址 / 端口</td><td>如 <code>127.0.0.1:6379</code></td></tr><tr><td>密码</td><td>无密码可留空</td></tr><tr><td>库编号</td><td>默认 <code>0</code></td></tr><tr><td>缓存前缀</td><td>如 <code>lingmeng</code>，多站点同 Redis 时 <strong>必须不同</strong></td></tr></tbody></table><h3 id="meilisearch-搜索-可选" tabindex="-1">Meilisearch 搜索（可选） <a class="header-anchor" href="#meilisearch-搜索-可选" aria-label="Permalink to &quot;Meilisearch 搜索（可选）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>启用</td><td>未部署 Docker 搜索服务则 <strong>关闭</strong></td></tr><tr><td>服务地址</td><td>默认 <code>http://127.0.0.1:7700</code></td></tr><tr><td>API Key</td><td>与 docker-compose 中 Master Key 一致</td></tr></tbody></table><p>→ 见 <a href="/ops/docker-infra">可选基础设施</a></p><h3 id="gorse-推荐-可选" tabindex="-1">Gorse 推荐（可选） <a class="header-anchor" href="#gorse-推荐-可选" aria-label="Permalink to &quot;Gorse 推荐（可选）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>启用</td><td>未部署则关闭</td></tr><tr><td>服务地址</td><td>默认 <code>http://127.0.0.1:8087</code></td></tr><tr><td>API Key</td><td>与部署配置一致</td></tr></tbody></table><hr><h2 id="步骤-03-安全与密钥" tabindex="-1">步骤 03：安全与密钥 <a class="header-anchor" href="#步骤-03-安全与密钥" aria-label="Permalink to &quot;步骤 03：安全与密钥&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>登录密钥</td><td><strong>必填</strong></td><td>JWT 签名，点 <strong>生成登录密钥</strong> 随机即可</td></tr><tr><td>登录有效期（小时）</td><td>推荐</td><td>如 <code>168</code>（7 天）</td></tr><tr><td>数据加密密钥</td><td>可选</td><td>留空自动生成；<strong>生产留空后勿丢 config.yaml</strong></td></tr><tr><td>文件签名密钥</td><td>可选</td><td>私有文件访问签名</td></tr><tr><td>管理员兼容旧版权限</td><td>新站 <strong>关闭</strong></td><td>开启会导致未配 Grant 的管理员权限过宽</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">密钥备份</p><p>安装完成后 <strong>备份 config.yaml</strong>（含所有密钥）。丢失后用户登录态、加密数据可能无法恢复。</p></div><hr><h2 id="步骤-04-确认安装" tabindex="-1">步骤 04：确认安装 <a class="header-anchor" href="#步骤-04-确认安装" aria-label="Permalink to &quot;步骤 04：确认安装&quot;">​</a></h2><ol><li>点击 <strong>测试连接</strong> — 验证 MySQL、Redis、已启用的 Meilisearch/Gorse</li><li>全部通过后点 <strong>确认安装</strong></li><li>等待建表进度条完成</li><li>记录页面显示的 <strong>管理员账号密码</strong>（默认可能为 <code>admin</code> / <code>admin123</code>）</li><li><strong>按提示重启</strong> Go 服务</li></ol><p>安装成功后 <code>/setup</code> 不可再访问。</p><hr><h2 id="安装完成后必做清单" tabindex="-1">安装完成后必做清单 <a class="header-anchor" href="#安装完成后必做清单" aria-label="Permalink to &quot;安装完成后必做清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>操作</th><th>路径</th></tr></thead><tbody><tr><td>1</td><td>修改管理员密码</td><td>管理后台登录 → 个人设置</td></tr><tr><td>2</td><td>完善网站信息</td><td><strong>系统设置 → 网站信息</strong></td></tr><tr><td>3</td><td>配置文件存储</td><td><strong>系统配置 → 文件存储</strong></td></tr><tr><td>4</td><td>配置微信（若需要）</td><td><strong>系统配置 → 微信小程序/公众号</strong></td></tr><tr><td>5</td><td>搭建首页 UI</td><td><a href="/features/ui-editor/scenarios/homepage">从零搭建首页</a></td></tr><tr><td>6</td><td>生产核对</td><td><a href="/ops/checklist">上线检查清单</a></td></tr></tbody></table><hr><h2 id="高级设置-「更多设置」折叠区" tabindex="-1">高级设置（「更多设置」折叠区） <a class="header-anchor" href="#高级设置-「更多设置」折叠区" aria-label="Permalink to &quot;高级设置（「更多设置」折叠区）&quot;">​</a></h2><p>安装时一般 <strong>不必展开</strong>。以下为运维调优项，安装后也可直接改 <code>config.yaml</code>：</p><table tabindex="0"><thead><tr><th>分区</th><th>典型字段</th></tr></thead><tbody><tr><td>数据库连接池</td><td>最大连接数、连接存活时间</td></tr><tr><td>日志</td><td>目录、JSON 格式、慢请求阈值</td></tr><tr><td>HTTP 服务</td><td>读/写超时、Brotli 压缩</td></tr><tr><td>全局限流</td><td>IP/用户维度 QPS</td></tr><tr><td>定时任务</td><td>是否启用调度</td></tr><tr><td>Prometheus</td><td>监控指标开关</td></tr></tbody></table><p>新站点保持默认即可，遇性能问题再调整。</p><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>向导打不开</strong></p><ul><li>服务未启动或防火墙未放行端口</li><li><code>setup_completed</code> 已为 <code>true</code>（已安装过）</li></ul><p><strong>测试连接失败</strong></p><ul><li>MySQL：库不存在、密码错、远程未授权</li><li>Redis：密码错、bind 127.0.0.1 导致容器不通</li></ul><p><strong>想重新安装</strong></p><ul><li>生产 <strong>不建议</strong>。须备份数据库 → 改 <code>setup_completed: false</code> → 清库或新库 → 再走向导</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/guide/quick-start">快速部署</a></li><li><a href="/guide/admin-access">进入管理后台</a></li><li><a href="/config/system-settings">系统配置总览</a></li></ul>`,61)])])}const u=d(s,[["render",h]]);export{g as __pageData,u as default};
